    public MainForm(){selected=ReadSelection();Text="AppForge — FIX MY SETUP";StartPosition=FormStartPosition.CenterScreen;MinimumSize=new Size(860,650);Size=new Size(1040,780);BackColor=Color.FromArgb(7,15,27);ForeColor=Color.White;Font=new Font("Segoe UI",10);try{Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);}catch{} BuildUi();Shown+=async(_,_)=>{if(selected.Count>0)await ScanAsync();};}

    void BuildUi(){
        var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(26),RowCount=7,ColumnCount=1,BackColor=BackColor};root.RowStyles.Add(new(SizeType.AutoSize));root.RowStyles.Add(new(SizeType.AutoSize));root.RowStyles.Add(new(SizeType.AutoSize));root.RowStyles.Add(new(SizeType.AutoSize));root.RowStyles.Add(new(SizeType.Percent,100));root.RowStyles.Add(new(SizeType.AutoSize));root.RowStyles.Add(new(SizeType.AutoSize));Controls.Add(root);
        var title=new Label{AutoSize=true,Text="AppForge  •  FIX MY SETUP",Font=new Font("Segoe UI",28,FontStyle.Bold),ForeColor=Color.White};root.Controls.Add(title);
        var sub=new Label{AutoSize=true,Text=selected.Count>0?"Scanning your selected apps: missing → install, old → update, current → skip.":"No website selection found. Download a fresh AppForge setup from the website.",ForeColor=Color.FromArgb(155,170,191),Margin=new Padding(0,2,0,10)};root.Controls.Add(sub);
        summary.AutoSize=true;summary.Text=selected.Count>0?"PC Health: waiting for scan…":"Selection missing";summary.ForeColor=Color.FromArgb(103,210,255);summary.Font=new Font("Segoe UI",10,FontStyle.Bold);summary.Margin=new Padding(0,0,0,10);root.Controls.Add(summary);
        var tools=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill,FlowDirection=FlowDirection.LeftToRight,Margin=new Padding(0,0,0,10)};StyleButton(scan,"Scan again",false);StyleButton(retry,"Retry failed",false);StyleButton(copyErrors,"Copy errors",false);StyleButton(cancel,"Cancel",false);scan.Click+=async(_,_)=>await ScanAsync();retry.Click+=async(_,_)=>await FixAsync(true);copyErrors.Click+=(_,_)=>CopyErrors();cancel.Click+=(_,_)=>{cts?.Cancel();try{active?.Kill(true);}catch{}};retry.Enabled=false;copyErrors.Enabled=false;cancel.Enabled=false;tools.Controls.AddRange([scan,retry,copyErrors,cancel]);root.Controls.Add(tools);
        appList.Dock=DockStyle.Fill;appList.FlowDirection=FlowDirection.TopDown;appList.WrapContents=false;appList.AutoScroll=true;appList.BackColor=Color.FromArgb(10,22,37);appList.Padding=new Padding(12);root.Controls.Add(appList);
        if(selected.Count>0)foreach(var a in selected)AddRow(a);else appList.Controls.Add(new Label{Width=900,Height=100,Text="Go back to AppForge → choose apps → Get my apps → download a fresh installer.",TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(155,170,191)});
        var pr=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,AutoSize=true,Margin=new Padding(0,14,0,8)};pr.ColumnStyles.Add(new(SizeType.Percent,100));pr.ColumnStyles.Add(new(SizeType.AutoSize));overall.Dock=DockStyle.Fill;overall.Height=16;counter.AutoSize=true;counter.Text=$"0 / {selected.Count}";counter.ForeColor=Color.FromArgb(155,170,191);counter.Margin=new Padding(12,0,0,0);pr.Controls.Add(overall,0,0);pr.Controls.Add(counter,1,0);root.Controls.Add(pr);
